import {bicField,installBicUI,renderDirectoryPage} from './bic-ui.mjs';
import {BUILTIN,HEADER_TEMPLATE,BAH_VERSIONS,upgradeDraft,restoreState,defaults,freshIds,generate,headerXML,escapeXML as esc,validatePackage} from './engine.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const STORE='mwtsi-integrated-payment-lab-v1:'+new URLSearchParams(location.search).get('scope');
let persisted={};try{persisted=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
let imported=[];for(const p of persisted.packages||[]){try{imported.push(validatePackage(p))}catch{}}
let packs=[BUILTIN,...imported],active=packs.find(p=>p.id===persisted.activeId)||BUILTIN;
let s=upgradeDraft(persisted.draft);if(!BUILTIN.profiles.some(p=>p.key===s.type))s.type='pacs008';
let saved=Array.isArray(persisted.saved)?persisted.saved:[],adapter=persisted.adapter||{sourceCode:'WSN',requestType:'HV_NON_PASS_THROUGH',headerTemplate:HEADER_TEMPLATE};
let tab='payment',view='',current=null,manualXML=null,editing=false,validationToken=0,checkTimer,toastTimer;
const main=$('#main'),modal=$('#modal');
const outputNames={document:'ISO Document',envelope:'ACI UPF envelope',aci:'ACI header only',bah:'Business header only'};
const icons={save:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M5 3h12l4 4v14H3V3h2Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/></svg>',download:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg>',copy:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/></svg>'};
function persist(){try{localStorage.setItem(STORE,JSON.stringify({packages:packs.filter(p=>p.id!==BUILTIN.id),activeId:active.id,draft:s,saved,adapter}));return true}catch{toast('Browser storage is full or unavailable. Export your work to keep it.');return false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('toast');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast'),4200)}
function field(key,label,{type='text',options,help,full=false,mono=false,max,optional=false}={}){return `<div class="field ${full?'full':''}"><label for="${key}">${label}${optional?'<span class="optional">Optional</span>':''}</label>${key.endsWith('Bic')?bicField(key,s[key]):options?`<select id="${key}" data-field="${key}">${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(s[key])===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`:type==='textarea'?`<textarea id="${key}" data-field="${key}" ${max?'maxlength="'+max+'"':''}>${esc(s[key])}</textarea>`:`<input id="${key}" data-field="${key}" type="${type}" ${type==='number'?'step="0.01" min="0.01"':''} value="${esc(s[key])}" ${max?'maxlength="'+max+'"':''} class="${mono?'mono':''}" autocomplete="off">`}${help?`<div class="field-help">${help}</div>`:''}</div>`}
function section(label,content){return `<section class="form-section"><div class="section-label">${label}</div><div class="form-grid">${content}</div></section>`}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function navigation(){view=location.hash.slice(1)||'studio';if(!['studio','scenarios','standards','adapter','directory'].includes(view))view='studio';$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#breadcrumb').textContent={studio:'Message studio',scenarios:'Saved scenarios',standards:'Standards library',adapter:'Adapter profiles',directory:'BIC directory'}[view];$('#scenario-count').textContent=saved.length;validationToken++;if(view==='studio')renderStudio();if(view==='scenarios')renderScenarios();if(view==='standards')renderStandards();if(view==='adapter')renderAdapter();if(view==='directory')renderDirectoryPage(main);}
function renderStudio(){
 const profile=active.profiles.find(p=>p.key===s.type);if(!profile){s.type=active.profiles[0].key;}
 main.innerHTML=heading('PAYMENT MESSAGING / ISO 20022','Build a payment message.','A focused workspace to create, validate, and export test messages.',`<button class="button" data-action="save">${icons.save} Save scenario</button>`)+`
 <div class="standards-strip"><div class="strip-left"><span class="strip-symbol">◈</span><strong>${esc(active.name)}</strong><span class="divider"></span><span class="strip-muted">Versioned baseline · ISO schemas installed</span></div><button class="strip-link" data-action="standards">Manage standards <span>↗</span></button></div>
 <div class="type-header"><span>01 <span class="muted">/</span> Choose your message</span><span class="micro-label">SWIFT / FINPLUS</span></div>
 <div class="type-grid" role="group" aria-label="Message type">${active.profiles.map(p=>`<button class="type-card ${s.type===p.key?'selected':''}" data-type="${p.key}" aria-pressed="${s.type===p.key}"><span class="radio-dot"></span><span class="type-title">${esc(p.label.replace(' COV',''))}${p.key==='pacs009cov'?'<span class="cov-tag">COV</span>':''}</span><span class="type-description">${esc(p.name)}</span></button>`).join('')}</div>
 <div class="studio-grid"><div><section class="panel"><div class="panel-title"><div><h2>Message configuration</h2><p>Set the details for your test payment.</p></div><span class="mono">02 / CONFIGURE</span></div>
 <div class="tabs" role="tablist" aria-label="Message configuration">${[['payment','Payment details'],['parties','Parties & agents'],['header','Header & output']].map(([k,l],i)=>`<button role="tab" aria-selected="${tab===k}" aria-controls="form-content" class="tab ${tab===k?'active':''}" data-tab="${k}"><span class="tab-num">0${i+1}</span>${l}</button>`).join('')}</div>
 <div class="panel-body" id="form-content" role="tabpanel">${formContent()}</div><div class="form-bottom"><small>One message. One test transaction.</small><button class="button primary" data-action="generate"><span>↻</span> Regenerate IDs & XML</button></div></section>
 <div class="negative-strip"><div><strong>Test the edge cases.</strong><p>Introduce a deliberate error to exercise your validators.</p></div><label class="switch"><input type="checkbox" id="negative-toggle" ${s.mode==='negative'?'checked':''}><span class="switch-track"></span><span>Negative test</span></label></div>
 ${s.mode==='negative'?`<div class="negative-options">${field('negative','Error to introduce',{options:[['missing-amount','Missing required amount · XSD failure'],['invalid-bic','Invalid BIC format · XSD failure'],['invalid-currency','Invalid currency format · XSD failure'],['count-mismatch','Transaction count mismatch · local rule failure']]})}</div>`:''}
 </div><div><section class="panel preview-panel"><div class="preview-head"><h2><span>&lt;/&gt;</span> XML preview</h2><select id="output-select" aria-label="XML output format">${Object.entries(outputNames).map(([v,t])=>`<option value="${v}" ${s.output===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="file-bar"><span class="file-dot"></span><span id="filename"></span><span class="file-size" id="file-size"></span></div><div id="code-view"></div><div class="code-toolbar"><span class="encoding">XML · UTF-8 <span id="line-count"></span></span><div class="toolbar-actions"><button class="button ghost" data-action="edit" id="edit-button">Edit XML</button><button class="button" data-action="copy">${icons.copy} Copy</button><button class="button dark" data-action="download">${icons.download} .xml</button></div></div></section>
 <section class="panel validation-panel"><div class="validation-head"><h2>Validation results</h2><span class="validation-summary" id="validation-summary">CHECKING</span></div><div class="validation-body" id="validation-results" aria-live="polite"></div><div class="validation-links"><span>Scope: base XSD + selected local rules</span><a href="#standards">View coverage ↗</a></div></section></div></div>`;
 updatePreview();
}
function formContent(){
 if(tab==='payment')return section('PAYMENT INFORMATION',field('amount',s.type==='pain001'?'Instructed amount':'Settlement amount',{type:'number'})+field('currency','Currency',{options:['USD','EUR','GBP','JPY','CAD','CHF','AUD','SGD']})+field('valueDate',s.type==='pain001'?'Requested execution date':'Settlement date',{type:'date'})+field(s.type==='pain001'?'chargeBearer':'settlement',s.type==='pain001'?'Charge bearer':'Settlement method',{options:s.type==='pain001'?[['SHAR','SHAR · Shared'],['DEBT','DEBT · Debtor'],['CRED','CRED · Creditor']]:[['INDA','INDA · Instructed agent'],['INGA','INGA · Instructing agent']]})+(s.type==='pacs008'?field('chargeBearer','Charge bearer',{options:[['SHAR','SHAR · Shared'],['DEBT','DEBT · Debtor'],['CRED','CRED · Creditor']]}):''))+
 section('MESSAGE IDENTIFICATION',field('messageId','Message ID',{mono:true,max:35})+field('endToEndId','End-to-end ID',{mono:true,max:35})+(s.type!=='pain001'?field('uetr','UETR',{mono:true,full:true,max:36,help:'Generated UUID v4. Retained until you regenerate identifiers.'}):'')+field('remittance','Remittance information',{full:true,type:'textarea',max:140,optional:true}))+
 `<div class="info-note"><span class="info-icon">ⓘ</span><span>Synthetic data is prefilled. Choose published BIC references in Parties & agents, or keep synthetic test values.</span></div>`;
 if(tab==='parties')return partiesForm();
 return section('OUTPUT FORMAT',field('output','Export content',{full:true,options:Object.entries(outputNames)}))+
 section('ACI UPF BANK ADAPTER',field('sourceCode','SourceCode',{mono:true,help:'Configurable per scenario. Default: '+esc(adapter.sourceCode)})+field('requestType','RequestType',{mono:true}))+section('BUSINESS APPLICATION HEADER',field('bahVersion','Header version',{full:true,options:BAH_VERSIONS.map(v=>[v,v+(v.endsWith('.03')?' · matches supplied ACI example':' · alternate version')])}))+
 `<div class="form-section"><div class="section-label">BUSINESS SERVICE</div><label class="switch"><input type="checkbox" data-field="includeBizSvc" ${s.includeBizSvc?'checked':''}><span class="switch-track"></span>Include BizSvc in AppHdr</label><div class="field-help spaced">Off by default to match your ACI example. Enable when required by the selected service.</div></div>
 <div class="info-note"><span class="info-icon">ⓘ</span><span>ACI UPF envelope includes RTPSHdr and BusMsg containing AppHdr + Document. The XML declaration is included in every export. <a href="#adapter">Edit ACI header template ↗</a></span></div>`;
}

function roleCard(flag,title,path,content){return s[flag]?`<section class="role-card"><div class="role-heading"><div><h3>${title}</h3><small>${path}</small></div><button class="button small" data-remove-role="${flag}" aria-label="Remove ${title}">Remove</button></div><div class="form-grid">${content}</div></section>`:`<button class="role-add" data-add-role="${flag}"><span>+</span> Add ${title.toLowerCase()} <small>${path}</small></button>`;}
function ultimateFields(prefix,financial){return financial?field(prefix+'Bic','Institution BIC',{mono:true,max:11}):field(prefix+'Name','Name',{full:true,max:140})+field(prefix+'City','Town / city',{max:35,optional:true})+field(prefix+'Country','Country code',{max:2,optional:true});}
function ultimateRoles(underlying=false){const financial=s.type.startsWith('pacs009')&&!underlying,prefix=underlying?'underlyingUltimate':'ultimate',path=underlying?'UndrlygCstmrCdtTrf / ':'';return `<div class="form-section"><div class="section-label">${underlying?'UNDERLYING CUSTOMER · ULTIMATE PARTIES':'ULTIMATE PARTIES'}</div>${['Debtor','Creditor'].map(role=>roleCard('include'+prefix[0].toUpperCase()+prefix.slice(1)+role,'Ultimate '+role.toLowerCase(),path+(role==='Debtor'?'UltmtDbtr':'UltmtCdtr'),ultimateFields(prefix+role,financial))).join('')}</div>`;}
function intermediaryRoles(underlying=false){const prefix=underlying?'underlyingIntermediary':'intermediary',path=underlying?'UndrlygCstmrCdtTrf / ':'';return `<div class="form-section"><div class="section-label">${underlying?'UNDERLYING CUSTOMER · INTERMEDIARY AGENTS':'INTERMEDIARY AGENTS'}</div>${[1,2,3].map(i=>roleCard('include'+prefix[0].toUpperCase()+prefix.slice(1)+i,'Intermediary agent '+i,path+'IntrmyAgt'+i,field(prefix+i+'Bic','BIC',{mono:true,max:11})+field(prefix+i+'Account','Agent account ID',{mono:true,max:34,optional:true}))).join('')}</div>`;}
function partiesForm(){
 const fi=s.type.startsWith('pacs009'),cov=s.type==='pacs009cov';
 let html=`<div class="info-note" style="margin:0 0 19px"><span class="info-icon">ⓘ</span><span>${cov?'Configure the cover institutions and their agents separately from the underlying customer-payment parties below.':fi?'Creditor institution (Cdtr) and creditor agent (CdtrAgt) are distinct roles. Add optional agents and ultimate institutions below.':'Set debtor and creditor agents, customer parties, and optional ultimate parties below.'}</span></div>`;
 html+=section('MESSAGE ROUTING',field('senderBic','Instructing / sender BIC',{mono:true,max:11})+field('receiverBic','Instructed / receiver BIC',{mono:true,max:11}));
 if(fi){
  html+=section(cov?'COVER PAYMENT · INSTITUTIONS':'PAYMENT · INSTITUTIONS',field('debtorBic','Debtor institution BIC · Dbtr',{mono:true,max:11})+field('creditorBic','Creditor institution BIC · Cdtr',{mono:true,max:11})+field('institutionDebtorAccount','Debtor institution account',{mono:true,max:34,optional:true})+field('institutionCreditorAccount','Creditor institution account',{mono:true,max:34,optional:true}));
  html+=`<div class="form-section"><div class="section-label">${cov?'COVER PAYMENT · AGENTS':'PAYMENT · AGENTS'}</div>${roleCard('includeDebtorAgent','Debtor agent','DbtrAgt',field('debtorAgentBic','Debtor agent BIC',{mono:true,max:11})+field('debtorAgentAccount','Agent account ID',{mono:true,max:34,optional:true}))}${roleCard('includeCreditorAgent','Creditor agent','CdtrAgt',field('creditorAgentBic','Creditor agent BIC',{mono:true,max:11})+field('creditorAgentAccount','Agent account ID',{mono:true,max:34,optional:true}))}</div>`;
 }else html+=section('PAYMENT · AGENTS',field('debtorBic','Debtor agent BIC · DbtrAgt',{mono:true,max:11})+field('creditorBic','Creditor agent BIC · CdtrAgt',{mono:true,max:11})+field('debtorAgentAccount','Debtor agent account ID',{mono:true,max:34,optional:true})+field('creditorAgentAccount','Creditor agent account ID',{mono:true,max:34,optional:true}));
 html+=intermediaryRoles()+ultimateRoles();
 if(cov)html+=section('UNDERLYING CUSTOMER · AGENTS',field('underlyingDebtorAgentBic','Underlying debtor agent BIC',{mono:true,max:11,help:'UndrlygCstmrCdtTrf / DbtrAgt'})+field('underlyingCreditorAgentBic','Underlying creditor agent BIC',{mono:true,max:11,help:'UndrlygCstmrCdtTrf / CdtrAgt'})+field('underlyingDebtorAgentAccount','Debtor agent account ID',{mono:true,max:34,optional:true})+field('underlyingCreditorAgentAccount','Creditor agent account ID',{mono:true,max:34,optional:true}));
 if(!fi||cov){for(const role of ['debtor','creditor'])html+=section((cov?'UNDERLYING CUSTOMER · ':'CUSTOMER · ')+role.toUpperCase(),field(role+'Name','Name',{full:true,max:140})+field(role+'Account','Account ID',{full:true,mono:true,max:34})+field(role+'City','Town / city',{max:35})+field(role+'Country','Country code',{max:2})+field(role+'Postal','Postal code',{max:16,optional:true})+field(role+'Subdivision','State / province',{max:35,optional:true})+field(role+'AddressLine1','Address line 1',{max:70,full:true,optional:true})+field(role+'AddressLine2','Address line 2',{max:70,full:true,optional:true}));}
 if(cov)html+=intermediaryRoles(true)+ultimateRoles(true);
 return html;
}

function filename(){return `${s.type==='pacs009cov'?'pacs.009-COV':current?.profile.messageId||'payment'}_${s.mode==='negative'?'NEGATIVE-':''}TEST_${s.messageId.replace(/[^a-zA-Z0-9_-]/g,'').slice(0,35)||'message'}${s.output==='document'?'':'_'+s.output}.xml`}
function syntax(line){return esc(line).replace(/(&lt;\?.*?\?&gt;)/g,'<span class="xml-meta">$1</span>').replace(/(&lt;\/?)([\w:]+)/g,'<span class="xml-tag">$1$2</span>').replace(/([\w:]+)=(&quot;.*?&quot;)/g,'<span class="xml-attr">$1</span>=<span class="xml-value">$2</span>')}
function renderCode(xml){if(!$('#code-view'))return;const code=$('#code-view');if(editing){code.innerHTML='<div class="editor-banner">Manual XML edits are validated as written. Changing the form regenerates the XML.</div><textarea class="editor-input" id="xml-editor" aria-label="Edit generated XML" spellcheck="false"></textarea>';$('#xml-editor').value=xml;}else code.innerHTML=`${manualXML!==null?'<div class="editor-banner">Manual XML · validation applies to the edited output.</div>':''}<div class="code-area" tabindex="0" aria-label="XML source">${xml.split('\n').map((l,i)=>`<div class="code-line"><span class="line-number">${i+1}</span><span class="code-text">${syntax(l)}</span></div>`).join('')}</div>`;
 $('#filename').textContent=filename();$('#file-size').textContent=(new TextEncoder().encode(xml).length/1024).toFixed(1)+' KB';$('#line-count').textContent='· '+xml.split('\n').length+' lines';$('#edit-button').textContent=editing?'Apply & validate':'Edit XML';}
function outputXML(){return manualXML??current?.xml??''}
function updatePreview(){try{current=generate(s,active);manualXML=null;editing=false;renderCode(current.xml);queueValidation()}catch(e){$('#code-view').innerHTML=`<div class="error-box">${esc(e.message)}</div>`;toast(e.message)}}
function queueValidation(){clearTimeout(checkTimer);const token=++validationToken;$('#validation-summary').textContent='CHECKING';$('#validation-results').innerHTML=checkRow('wait','Validating current XML','Parsing output and checking the selected base schema.');checkTimer=setTimeout(()=>runValidation(token),250)}
function checkRow(status,title,detail='',path=''){return `<div class="check-row"><span class="check-icon ${status==='pass'?'':status}">${{pass:'✓',fail:'×',warn:'!',wait:'·'}[status]}</span><div><strong>${esc(title)}</strong>${detail?`<p>${esc(detail)}</p>`:''}${path?`<p class="path">${esc(path)}</p>`:''}</div><span class="check-status">${{pass:'PASS',fail:'FAIL',warn:'PARTIAL',wait:'WAIT'}[status]}</span></div>`}
function parseXML(xml){if(xml.length>400000)throw Error('XML exceeds the 400 KB test-message limit.');if(/<!DOCTYPE|<!ENTITY/i.test(xml))throw Error('DTD and entity declarations are not accepted.');const d=new DOMParser().parseFromString(xml,'application/xml');if(d.getElementsByTagName('parsererror').length||d.documentElement.localName==='parsererror')throw Error('XML is not well formed. Check tag nesting, namespaces, and escaped characters.');return d;}
const child=(node,name)=>[...node.children].find(n=>n.localName===name);
const descendants=(node,name)=>[...node.getElementsByTagName('*')].filter(n=>n.localName===name);
function atPath(root,path){let nodes=[root];const names=path.split('/');if(root.localName!==names.shift())return [];for(const n of names)nodes=nodes.flatMap(e=>[...e.children].filter(c=>c.localName===n));return nodes;}
const schemaCache=new Map();async function schemaText(mid){if(!schemaCache.has(mid)){const res=await fetch('schemas/'+mid+'.xsd');if(!res.ok)throw Error('Schema could not be loaded: '+mid);schemaCache.set(mid,await res.text())}return schemaCache.get(mid)}
async function xsdCheck(xml,schema){const {validateXML}=await import('./vendor/xmllint/index-browser.mjs');return await validateXML({xml:[{fileName:'payment.xml',contents:xml}],schema:[{fileName:'message.xsd',contents:schema}],initialMemoryPages:256,maxMemoryPages:512});}
async function runValidation(token){
 const rows=[];let failures=0,expectedDetected=false;
 const push=(status,title,detail,path)=>{rows.push(checkRow(status,title,detail,path));if(status==='fail')failures++};
 try{
  const xml=outputXML(),doc=parseXML(xml);push('pass','Well-formed XML','Single root element · UTF-8 export');
  const root=doc.documentElement;
  const isEnvelope=root.localName==='RTPSMsg';
  const bus=isEnvelope?child(root,'BusMsg'):null;
  let payment=root.localName==='Document'?root:bus?child(bus,'Document'):null;
  let bah=root.localName==='AppHdr'?root:bus?child(bus,'AppHdr'):null;
  let aci=root.localName==='RTPSHdr'?root:isEnvelope?child(root,'RTPSHdr'):null;
  const needsPayment=['document','envelope'].includes(s.output),needsBah=['bah','envelope'].includes(s.output),needsAci=['aci','envelope'].includes(s.output);
  if(needsPayment&&!payment)push('fail','ISO Document missing','Selected output requires an ISO Document element inside BusMsg.');
  if(needsBah&&!bah)push('fail','Business header missing','AppHdr is required inside BusMsg for the ACI envelope.');
  if(needsAci&&!aci)push('fail','ACI header missing','RTPSHdr is required by this output configuration.');
  const requiredRoot={document:'Document',envelope:'RTPSMsg',aci:'RTPSHdr',bah:'AppHdr'}[s.output];if(root.localName!==requiredRoot)push('fail','Unexpected output root','Expected '+requiredRoot+' for the selected output.');
  if(s.output==='envelope'){
   const children=[...root.children],contents=bus?[...bus.children]:[];
   const valid=isEnvelope&&root.namespaceURI==='urn:rtps.bank'&&children.length===2&&children[0]===aci&&children[1]===bus&&!aci.namespaceURI&&!bus.namespaceURI&&contents.length===2&&contents[0]===bah&&contents[1]===payment;
   push(valid?'pass':'fail','ACI envelope structure',valid?'RTPSMsg (urn:rtps.bank) → RTPSHdr + BusMsg → AppHdr + Document':'Expected namespaced RTPSMsg with unqualified RTPSHdr and BusMsg, followed by AppHdr and Document inside BusMsg.');
  }
  if(payment){
   const schema=current.profile.schema||await schemaText(current.profile.messageId);
   const result=await xsdCheck(new XMLSerializer().serializeToString(payment),schema);
   if(token!==validationToken)return;
   push(result.valid?'pass':'fail','ISO 20022 base schema',result.valid?current.profile.messageId+' · official ISO schema':result.errors.map(e=>e.message).slice(0,3).join('\n'),'Document');
   if(!result.valid&&s.mode==='negative'&&['missing-amount','invalid-bic','invalid-currency'].includes(s.negative))expectedDetected=true;
   const counts=descendants(payment,'NbOfTxs');const txs=descendants(payment,'CdtTrfTxInf');const countOK=counts.length>0&&counts.every(c=>c.textContent===String(txs.length));
   push(countOK?'pass':'fail','Transaction count',countOK?'Declared count matches '+txs.length+' transaction.':'NbOfTxs must match the actual number of CdtTrfTxInf elements.','Document/.../NbOfTxs');if(!countOK&&s.mode==='negative'&&s.negative==='count-mismatch')expectedDetected=true;
   const amounts=[...descendants(payment,'IntrBkSttlmAmt'),...descendants(payment,'InstdAmt')];const amountOK=amounts.length>0&&amounts.every(n=>/^\d+(?:\.\d+)?$/.test(n.textContent)&&Number(n.textContent)>0);push(amountOK?'pass':'fail','Positive payment amount',amountOK?'All payment amounts are greater than zero.':'Provide a positive decimal amount.');
   const under=descendants(payment,'UndrlygCstmrCdtTrf');if(s.type==='pacs009cov')push(under.length===1?'pass':'fail','COV underlying payment',under.length===1?'Underlying customer credit transfer is present.':'A COV scenario requires one UndrlygCstmrCdtTrf.');if(s.type==='pacs009'&&under.length)push('fail','Core scenario restriction','Use the COV profile for underlying customer-payment information.');
   for(const rule of active.rules.filter(r=>!r.profiles||r.profiles.includes(s.type))){const nodes=atPath(payment,rule.path);const ok=rule.check==='required'?nodes.some(n=>n.textContent.trim()):rule.check==='equals'?nodes.length>0&&nodes.every(n=>n.textContent===rule.value):nodes.every(n=>n.textContent.length<=rule.value);push(ok?'pass':'fail',rule.id,rule.message,rule.path)}
  }
  if(bah){const r=await xsdCheck(new XMLSerializer().serializeToString(bah),await schemaText(current.bahVersion));if(token!==validationToken)return;push(r.valid?'pass':'fail','Business Application Header',r.valid?current.bahVersion+' base schema passed.':r.errors.slice(0,2).map(e=>e.message).join('\n'));if(payment){const msg=descendants(payment,'MsgId')[0]?.textContent;const bid=child(bah,'BizMsgIdr')?.textContent;const def=child(bah,'MsgDefIdr')?.textContent;push(msg===bid&&def===current.profile.messageId?'pass':'fail','Header / document consistency','BizMsgIdr must match MsgId; MsgDefIdr must match the selected message profile.');}}
  if(aci){const h=child(aci,'ACITBHdr');const source=h&&child(h,'SourceCode'),request=h&&child(h,'RequestType');const valid=!aci.namespaceURI&&h&&!h.namespaceURI&&source&&!source.namespaceURI&&request&&!request.namespaceURI&&source.textContent.trim()&&request.textContent.trim()&&[...h.children].filter(n=>n.localName==='SourceCode').length===1&&[...h.children].filter(n=>n.localName==='RequestType').length===1;push(valid?'pass':'fail','ACI header structure',valid?'SourceCode: '+source.textContent+' · RequestType: '+request.textContent:'ACITBHdr must contain nonempty SourceCode and RequestType.');push('warn','ACI adapter compatibility unverified','Envelope and header layout follow your supplied image. Complete ACI adapter-schema validation is not installed.');}
  if(payment||bah)push('warn','SWIFT CBPR+ coverage incomplete','Base XSD and selected checks only. Complete SR2025 usage rules, current BIC registration and connectivity verification are not installed.');
  if(s.mode==='negative'&&payment)push(expectedDetected?'pass':'fail','Expected negative-test failure',expectedDetected?'The introduced error was detected.':'The selected error was not detected in the current XML.');
 }catch(e){push('fail','Validation could not complete',e.message)}
 if(token!==validationToken||!$('#validation-results'))return;
 $('#validation-results').innerHTML=rows.join('');$('#validation-summary').textContent=failures?`${failures} ${failures===1?'FAILURE':'FAILURES'}${s.mode==='negative'&&expectedDetected?' · EXPECTED':''}`:'CHECKS PASSED · PARTIAL';$('#validation-summary').style.background=failures?'#faece6':'#edf4e7';$('#validation-summary').style.color=failures?'#ac604d':'#79916c';
}
function download(text,name,type='application/xml'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function showModal(title,body,footer){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer||'<button class="button primary" data-action="close-modal">Done</button>'}</div>`;modal.showModal();}
function saveScenario(){showModal('Save test scenario',`<p>Keep the form, output settings, identifiers, and standards package together. Scenarios stay in this browser.</p><div class="field"><label for="scenario-name">Scenario name</label><input id="scenario-name" maxlength="100" value="${esc(current.profile.label+' · '+s.currency+' '+s.amount+(s.mode==='negative'?' · negative test':''))}"></div><div class="modal-error" id="save-error"></div>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-save">Save scenario</button>`);$('#scenario-name').select()}
function renderScenarios(){main.innerHTML=heading('YOUR TEST LIBRARY','A scenario for every case.','Save a known baseline, duplicate it, and explore what changes.',`<button class="button" data-action="export-scenarios">${icons.download} Export library</button><button class="button primary" data-action="studio">+ New message</button>`)+(saved.length?`<div class="saved-grid">${saved.map(item=>`<article class="panel saved-card"><div class="saved-top"><span class="tag">${esc(item.state.type==='pacs009cov'?'pacs.009 COV':item.package.profiles.find(p=>p.key===item.state.type)?.label||item.state.type)}</span><span class="tag ${item.state.mode==='negative'?'warning':'neutral'}">${item.state.mode==='negative'?'NEGATIVE':'POSITIVE'}</span></div><h2>${esc(item.name)}</h2><p>${esc(item.state.currency)} ${esc(item.state.amount)} <span class="muted">/</span> ${esc(item.package.name)}</p><div class="saved-meta">Saved ${esc(new Date(item.savedAt).toLocaleDateString())} · ${esc(item.state.sourceCode)}</div><div class="saved-actions"><button class="button primary small" data-load="${item.id}">Open scenario ↗</button><button class="button small" data-duplicate="${item.id}">Duplicate</button><button class="button small danger" data-delete="${item.id}" aria-label="Delete ${esc(item.name)}">Delete</button></div></article>`).join('')}</div>`:`<section class="panel empty-state"><div class="empty-icon">▤</div><h2>Your next test starts here.</h2><p>Save a message from the studio to keep its exact inputs and standards version for another test.</p><button class="button primary" data-action="studio">Create your first scenario ↗</button></section>`)+`<div class="info-note"><span class="info-icon">ⓘ</span><span>Browser-local storage is not a backup. Export your library to keep a portable JSON copy. <button class="strip-link" style="display:inline" data-action="import-scenarios">Import library ↗</button></span></div><input type="file" id="scenario-file" accept=".json,application/json" hidden>`;}
function renderStandards(){main.innerHTML=heading('VERSIONED SPECIFICATIONS','Standards that can evolve.','Keep your baseline reproducible. Add a new package when the rules change.',`<button class="button" data-action="package-template">${icons.download} Export package template</button>`)+`<div class="standard-grid"><div>${packs.map(p=>`<article class="panel standard-card"><div class="saved-top"><span class="tag ${p.id===active.id?'':'neutral'}">${p.id===active.id?'ACTIVE BASELINE':'AVAILABLE'}</span><span class="tag warning">PARTIAL RULE COVERAGE</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description||'Custom package. Imported rules extend the base schema checks.')}</p><div class="package-meta"><span>v${esc(p.version)}</span><span>Effective ${esc(p.effectiveDate)}</span><span>${p.rules.length} additional rules</span></div><table class="mini-table"><thead><tr><th>SCENARIO</th><th>ISO MESSAGE VERSION</th></tr></thead><tbody>${p.profiles.map(pr=>`<tr><td>${esc(pr.label)}</td><td>${esc(pr.messageId)}</td></tr>`).join('')}</tbody></table><div class="saved-actions">${p.id!==active.id?`<button class="button primary small" data-activate="${esc(p.id)}">Use this baseline</button>`:'<span class="privacy-chip">✓ Selected for new generation</span>'}<button class="button small" data-export-package="${esc(p.id)}">Export package</button></div></article>`).join('')}<div class="notice">2025 remains the selected historical test baseline. A release date or uploaded schema does not establish complete SWIFT compliance. Updates are never activated automatically.</div></div><div><section class="panel"><div class="panel-title"><h2>Bring the next release.</h2><span class="mono">IMPORT</span></div><div class="panel-body"><label class="upload-box"><span class="upload-icon">↥</span><strong>Import a standards package</strong><small>JSON · self-contained XSDs + declarative rules · up to 2 MB</small><input type="file" id="package-file" accept=".json,application/json"></label><p class="standards-note">Review version changes before activation. Existing saved scenarios retain their original package. Supported rules: required fields, exact values, and maximum lengths.</p><button class="button small" data-action="package-help">Package format guide ↗</button></div></section><section class="panel spaced"><div class="panel-title"><h2>Authoritative references</h2><span class="mono">SOURCES</span></div><div class="panel-body"><a class="resource" href="https://www.swift.com/products/mystandards" target="_blank" rel="noopener">SWIFT MyStandards <span>↗</span><small>Full CBPR+ usage guidelines · account access required</small></a><a class="resource" href="https://www.swift.com/insights/news/iso-20022-bytes-payments-maintaining-momentum-2025" target="_blank" rel="noopener">CBPR+ SR2025 announcement <span>↗</span><small>Release context and hybrid postal addresses</small></a><a class="resource" href="https://www.swift.com/sites/default/files/files/swift-compatible-application-payments_tvg_2025.pdf" target="_blank" rel="noopener">SWIFT 2025 validation guide <span>↗</span><small>Public technical reference</small></a><a class="resource" href="https://www.iso20022.org/catalogue-messages/iso-20022-messages-archive?search=pacs.008" target="_blank" rel="noopener">ISO 20022 message archive <span>↗</span><small>Source for the bundled official base XSDs</small></a><a class="resource" href="schemas/sources.json" target="_blank" rel="noopener">Schema provenance <span>↗</span><small>Source URLs and SHA-256 checksums</small></a><div class="info-note"><span class="info-icon">ⓘ</span><span>Fedwire and CHIPS profiles are planned for later releases. This version generates SWIFT-profile test messages only.</span></div></div></section></div></div>`;}
function renderAdapter(){main.innerHTML=heading('ADAPTER CONFIGURATION','The right header. Your defaults.','Configure the ACI UPF Bank Adapter header independently of the ISO message.',`<button class="button" data-action="reset-adapter">Reset example</button><button class="button primary" data-action="save-adapter">${icons.save} Save profile defaults</button>`)+`<div class="two-col"><section class="panel"><div class="panel-title"><h2>ACI UPF Bank Adapter</h2><span class="tag">LOCAL PROFILE</span></div><div class="panel-body"><div class="form-grid"><div class="field"><label for="adapter-source">Default SourceCode</label><input id="adapter-source" value="${esc(adapter.sourceCode)}" autocomplete="off"><span class="field-help">Applied when starting a new scenario.</span></div><div class="field"><label for="adapter-request">Default RequestType</label><input id="adapter-request" value="${esc(adapter.requestType)}" autocomplete="off"></div><div class="field full"><label for="adapter-template">Header template</label><textarea id="adapter-template" class="template-input" spellcheck="false">${esc(adapter.headerTemplate)}</textarea><span class="field-help">Use {{sourceCode}} and {{requestType}} placeholders. Values are XML-escaped. Keep RTPSHdr / ACITBHdr / SourceCode and RequestType.</span></div></div></div></section><div><section class="panel"><div class="panel-title"><h2>Resolved header preview</h2><button class="button small" data-action="download-header">${icons.download} .xml</button></div><div class="panel-body"><pre class="adapter-preview" id="adapter-preview"></pre><div class="info-note"><span class="info-icon">ⓘ</span><span>The initial structure and example values follow your supplied screenshot. Additional elements can be added in the template.</span></div></div></section><div class="notice spaced">Full ACI export follows the supplied RTPSMsg / RTPSHdr / BusMsg layout. Complete adapter field constraints still require the applicable UPF Bank Adapter specification.</div><p class="field-help">Saving defaults leaves existing scenarios unchanged. Apply the profile to the current draft using the action below.</p><button class="button spaced" data-action="apply-adapter">Apply saved profile to current draft ↗</button></div></div>`;updateAdapterPreview();}
function adapterDraft(){return {sourceCode:$('#adapter-source').value,requestType:$('#adapter-request').value,headerTemplate:$('#adapter-template').value}}
function updateAdapterPreview(){try{$('#adapter-preview').textContent=headerXML(adapterDraft())}catch(e){$('#adapter-preview').textContent=e.message}}
function checkHeader(a){const xml=headerXML(a),d=parseXML(xml),root=d.documentElement,h=child(root,'ACITBHdr');if(root.localName!=='RTPSHdr'||!h||!child(h,'SourceCode')?.textContent.trim()||!child(h,'RequestType')?.textContent.trim())throw Error('Header must contain RTPSHdr / ACITBHdr with nonempty SourceCode and RequestType.');return xml;}
async function exportPackage(pack,template=false){try{toast('Preparing package with its schemas…');const profiles=await Promise.all(pack.profiles.map(async p=>({...p,schema:p.schema||await schemaText(p.messageId)})));const result={...pack,profiles};if(template){result.id='custom-release-'+Date.now();result.name='My standards package';result.version='1.0.0';result.description='Custom package. Update the schemas, service identifiers, and rules for the intended release.';result.rules=[{id:'LOCAL-001',profiles:['pacs008'],path:'Document/FIToFICstmrCdtTrf/GrpHdr/MsgId',check:'required',message:'Message identification must be populated.'}];}download(JSON.stringify(result,null,2),template?'standards-package-template.json':pack.id+'.json','application/json');toast('Standards package exported.')}catch(e){toast(e.message)}}
function importFile(file,maxSize=2000000){if(!file)throw Error('No file selected.');if(file.size>maxSize)throw Error('File is too large. Maximum '+Math.round(maxSize/1000000)+' MB.');return file.text().then(t=>{try{return JSON.parse(t)}catch{throw Error('Choose a valid JSON file.')}})}
let pendingPackage=null;
async function reviewPackage(file){try{const pack=validatePackage(await importFile(file));if(packs.some(p=>p.id===pack.id))throw Error('That package ID already exists. Use a new ID to keep versions immutable.');for(const p of pack.profiles){const d=parseXML(p.schema);if(d.documentElement.localName!=='schema')throw Error('Invalid schema for '+p.label)}pendingPackage=pack;const diff=pack.profiles.map(p=>{const old=active.profiles.find(o=>o.key===p.key);return `<div class="diff-item"><strong>${esc(p.label)}</strong><br>${esc(old.messageId)} → ${esc(p.messageId)}<br><span class="muted">Service: ${esc(p.businessService)}</span></div>`}).join('');showModal('Review standards package',`<p><strong>${esc(pack.name)}</strong> · v${esc(pack.version)} · effective ${esc(pack.effectiveDate)}</p><div class="diff-list">${diff}<div class="diff-item">Additional rules: ${active.rules.length} → ${pack.rules.length}</div></div><p>Importing makes this package available. Activate it separately after reviewing your test results. Imported packages do not establish full SWIFT compliance.</p>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-package">Import package</button>`)}catch(e){toast(e.message)}}
function activate(pack){if(!active.profiles.some(p=>p.key===s.type))s.type='pacs008';active=pack;persist();renderStandards();toast(pack.name+' is now the active baseline. Saved scenarios are unchanged.');}
function help(){showModal('Your payment test workspace',`<p>Generate synthetic payment messages locally, inspect the XML, and copy or download it for testing.</p><ol><li>Choose a message type and enter your payment and party details.</li><li>Choose ISO Document, a separate ACI or Business Application Header, or the complete ACI UPF envelope.</li><li>Review actual base-XSD validation and selected local business checks.</li><li>Save a scenario to reproduce the exact inputs later, or enable a negative test to introduce an error.</li></ol><p>Complete SWIFT CBPR+ usage rules, current BIC registration/connectivity checks, and ACI envelope validation are not installed. Data stays in this browser; export your scenario library as a backup.</p><p>Keyboard: Tab through controls. In the configuration tabs, use left/right arrows to switch sections.</p>`)}
async function action(name){
 if(name==='close-modal'){modal.close();return}
 if(name==='studio'){s={...defaults(),...adapter};persist();if(view==='studio')renderStudio();else location.hash='studio';return}
 if(name==='standards'){location.hash='standards';return}
 if(name==='generate'){Object.assign(s,freshIds());persist();updatePreview();$('#form-content').innerHTML=formContent();toast('Fresh identifiers generated. XML updated.');return}
 if(name==='save'){saveScenario();return}
 if(name==='confirm-save'){const n=$('#scenario-name').value.trim();if(!n){$('#save-error').textContent='Enter a scenario name.';return}if(saved.length>=100){$('#save-error').textContent='Library limit reached (100 scenarios). Export and remove older scenarios.';return}saved.unshift({id:crypto.randomUUID(),name:n,state:{...s},package:structuredClone(active),manualXML,savedAt:new Date().toISOString()});persist();$('#scenario-count').textContent=saved.length;modal.close();toast('Scenario saved in this browser.');return}
 if(name==='copy'){const text=outputXML();try{await navigator.clipboard.writeText(text);toast('XML copied to clipboard.')}catch{showModal('Copy XML',`<p>Clipboard access is unavailable. Select the XML below and copy it.</p><textarea id="copy-fallback" class="template-input" aria-label="XML to copy"></textarea>`);$('#copy-fallback').value=text;$('#copy-fallback').select();}return}
 if(name==='download'){download(outputXML(),filename());toast('XML download prepared.');return}
 if(name==='edit'){if(editing){manualXML=$('#xml-editor').value;editing=false;renderCode(manualXML);queueValidation()}else{editing=true;renderCode(outputXML());$('#xml-editor').focus()}return}
 if(name==='export-scenarios'){download(JSON.stringify({format:'payment-message-lab-scenarios-v1',scenarios:saved},null,2),'payment-test-scenarios.json','application/json');return}
 if(name==='import-scenarios'){$('#scenario-file').click();return}
 if(name==='package-template'){await exportPackage(active,true);return}
 if(name==='confirm-package'){if(pendingPackage){packs.push(pendingPackage);persist();modal.close();pendingPackage=null;renderStandards();toast('Package imported. Activate it when ready.')}return}
 if(name==='package-help'){showModal('Standards package format',`<p>Start with <strong>Export package template</strong>. It contains the four profiles and complete bundled base XSDs.</p><ul><li>Give each release a unique <code>id</code>, <code>name</code>, <code>version</code>, and <code>effectiveDate</code>.</li><li>Each profile contains its message version, business service, and a self-contained XSD in <code>schema</code>.</li><li>Keep profile keys <code>pacs008</code>, <code>pacs009</code>, <code>pacs009cov</code>, and <code>pain001</code>.</li><li>Add rules using <code>path</code>, <code>check</code> (required, equals, maxLength), and <code>message</code>. Paths start with Document and use slash-separated XML element names.</li><li>Optionally scope a rule with <code>profiles</code>. No scripts, regex rules, external XSD imports, or DTDs are supported.</li></ul><p>A changed message version may require changes to the generator mapping. Run scenarios against each new package; schema incompatibilities appear as validation failures. Business Application Header supports head.001.001.03 (the ACI example default) and head.001.001.02, selectable in Header & output.</p>`);return}
 if(name==='save-adapter'){try{const a=adapterDraft();checkHeader(a);adapter=a;persist();toast('Adapter profile defaults saved.')}catch(e){toast(e.message)}return}
 if(name==='reset-adapter'){$('#adapter-source').value='WSN';$('#adapter-request').value='HV_NON_PASS_THROUGH';$('#adapter-template').value=HEADER_TEMPLATE;updateAdapterPreview();toast('Example restored. Save to keep these defaults.');return}
 if(name==='apply-adapter'){Object.assign(s,adapter);persist();toast('Saved adapter defaults applied to the draft.');return}
 if(name==='download-header'){try{const xml=checkHeader(adapterDraft());download('<?xml version="1.0" encoding="UTF-8"?>\n'+xml,'ACI-UPF-header-TEST.xml')}catch(e){toast(e.message)}return}
}
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;
 try{if(button.dataset.addRole||button.dataset.removeRole){const flag=button.dataset.addRole||button.dataset.removeRole;if(!/^include(?:DebtorAgent|CreditorAgent|Ultimate(?:Debtor|Creditor)|UnderlyingUltimate(?:Debtor|Creditor)|(?:Underlying)?Intermediary[123])$/.test(flag))return;s[flag]=!!button.dataset.addRole;persist();$('#form-content').innerHTML=formContent();updatePreview();if(s[flag])document.querySelector('[data-remove-role="'+flag+'"]')?.closest('.role-card')?.querySelector('input')?.focus({preventScroll:true});return}if(button.dataset.action)await action(button.dataset.action);if(button.dataset.type){s.type=button.dataset.type;persist();renderStudio()}if(button.dataset.tab){tab=button.dataset.tab;$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)});$('#form-content').innerHTML=formContent()}
 if(button.dataset.load){const item=saved.find(i=>i.id===button.dataset.load);if(!item)return;active=item.package;s=restoreState(item.state);if(!packs.some(p=>p.id===active.id))packs.push(active);persist();history.replaceState(null,'','#studio');navigation();if(item.manualXML!==null&&item.manualXML!==undefined){manualXML=item.manualXML;renderCode(manualXML);queueValidation()}toast('Scenario loaded with its saved standards package.');}
 if(button.dataset.duplicate){const item=saved.find(i=>i.id===button.dataset.duplicate);if(saved.length>=100)throw Error('Library limit reached (100 scenarios).');saved.unshift({...structuredClone(item),id:crypto.randomUUID(),name:item.name+' (copy)',savedAt:new Date().toISOString()});persist();navigation();toast('Scenario duplicated.');}
 if(button.dataset.delete){const item=saved.find(i=>i.id===button.dataset.delete);showModal('Delete scenario?',`<p>Remove <strong>${esc(item.name)}</strong> from this browser’s library?</p>`,`<button class="button" data-action="close-modal">Keep scenario</button><button class="button danger" data-confirm-delete="${item.id}">Delete scenario</button>`);}
 if(button.dataset.confirmDelete){saved=saved.filter(i=>i.id!==button.dataset.confirmDelete);persist();modal.close();navigation();toast('Scenario removed.');}
 if(button.dataset.activate){activate(packs.find(p=>p.id===button.dataset.activate))}
 if(button.dataset.exportPackage){await exportPackage(packs.find(p=>p.id===button.dataset.exportPackage))}
 }catch(err){toast(err.message)}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='xml-editor'){manualXML=el.value;queueValidation();return}if(el.dataset.field){const k=el.dataset.field;s[k]=el.type==='checkbox'?el.checked:el.value;if(k.endsWith('Country'))s[k]=s[k].toUpperCase();persist();if($('#output-select'))$('#output-select').value=s.output;updatePreview();}if(el.id.startsWith('adapter-'))updateAdapterPreview();});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='output-select'){s.output=el.value;persist();if(tab==='header')$('#form-content').innerHTML=formContent();updatePreview()}if(el.id==='negative-toggle'){s.mode=el.checked?'negative':'positive';persist();renderStudio()}if(el.id==='package-file'){await reviewPackage(el.files[0]);el.value=''}if(el.id==='scenario-file'){try{const data=await importFile(el.files[0],10000000);if(data.format!=='payment-message-lab-scenarios-v1'||!Array.isArray(data.scenarios)||data.scenarios.length>100||saved.length+data.scenarios.length>100)throw Error('Invalid library or more than 100 total scenarios.');const incoming=data.scenarios.map(i=>{if(typeof i.name!=='string'||i.name.length>100||!i.state||!['pacs008','pacs009','pacs009cov','pain001'].includes(i.state.type))throw Error('Invalid scenario in library.');let pack;if(i.package?.id===BUILTIN.id){if(JSON.stringify(i.package)!==JSON.stringify(BUILTIN))throw Error('Built-in package was modified. Export it with a new package ID.');pack=BUILTIN}else pack=validatePackage(i.package);const merged=restoreState(i.state);if(i.manualXML!=null&&(typeof i.manualXML!=='string'||i.manualXML.length>400000))throw Error('Invalid manual XML.');generate(merged,pack);return {...i,id:crypto.randomUUID(),package:pack,state:merged,savedAt:new Date().toISOString()}});saved=[...incoming,...saved];persist();navigation();toast('Scenario library imported.')}catch(err){toast(err.message)}el.value=''}});
document.addEventListener('keydown',e=>{const target=e.target.closest('[data-tab]');if(target&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=$$('[data-tab]');const i=tabs.indexOf(target);tabs[(i+(e.key==='ArrowRight'?1:2))%3].click();tabs[(i+(e.key==='ArrowRight'?1:2))%3].focus();}if(e.key==='Enter'&&modal.open&&$('#scenario-name')&&e.target.id==='scenario-name')action('confirm-save')});
$('#help-button').addEventListener('click',help);modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
installBicUI({getValue:key=>s[key],setValue:(key,value)=>{s[key]=value;persist();if(view==='studio')updatePreview();},notify:toast,modal:showModal,closeModal:()=>modal.close(),download});
window.addEventListener('hashchange',navigation);navigation();

// Parent bridge: address data is accepted only from the authenticated same-origin workspace.
window.addEventListener('message',event=>{
 if(event.source!==window.parent||event.origin!==location.origin||event.data?.type!=='MWTSI_PAYMENT_PREFILL')return;
 const role=event.data.role,p=event.data.party;let error='';
 if(!['debtor','creditor'].includes(role)||!p||typeof p!=='object')error='Invalid address handoff.';
 else if(s.type==='pacs009')error='Choose pacs.008, pacs.009 COV or pain.001 before loading a customer address.';
 else {const limits={name:140,city:35,country:2,postal:16,subdivision:35,addressLine1:70,addressLine2:70};for(const [key,max] of Object.entries(limits)){if(typeof p[key]!=='string'||Array.from(p[key]).length>max){error='Address field '+key+' needs review before loading.';break;}}}
 if(!error){for(const [key,value] of Object.entries(p)){const suffix={name:'Name',city:'City',country:'Country',postal:'Postal',subdivision:'Subdivision',addressLine1:'AddressLine1',addressLine2:'AddressLine2'}[key];if(suffix)s[role+suffix]=value;}persist();manualXML=null;if(view==='studio')renderStudio();toast('Reviewed address loaded as '+role+'. Payment remains a test draft.');}
 window.parent.postMessage({type:'MWTSI_PAYMENT_PREFILL_RESULT',requestId:event.data.requestId,error},location.origin);
});
if(window.parent!==window){window.parent.postMessage({type:'MWTSI_PAYMENT_LAB_READY'},location.origin);new ResizeObserver(()=>window.parent.postMessage({type:'MWTSI_PAYMENT_LAB_HEIGHT',height:Math.ceil(document.body.getBoundingClientRect().height)},location.origin)).observe(document.body);}
